33  export function mergeTranscript(local: string, merged: string): { text: string; notice: boolean } {
34    if (merged.length === 0) return { text: local, notice: false };
35    if (local.length === 0 || merged.startsWith(local)) return { text: merged, notice: false };
36    // The same run arriving again (or the candidate edited around it): already in the box.
37    if (local.includes(merged)) return { text: local, notice: false };
38    // A batch vendor answers once per press with a whole utterance, so a transcript that is
39    // not an evolution of what is in the box is new text: append it and never clobber the
40    // candidate's own words (M4's rule dropped it, which made every press after the first
41    // look like a no-op).
42    return { text: `${local}${merged}`, notice: true };
43  }

